export type ParsedRequestPaymentInstruction<
  TProgram extends string = typeof LEASH_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    agentKey: TAccountMetas[0];
    /** Pays the request's rent and gets it back when the request closes. Usually the agent key. */
    rentPayer: TAccountMetas[1];
    principal: TAccountMetas[2];
    agent: TAccountMetas[3];
    /** The allowlist entry for `payee`; required in `AllowListOnly` mode. */
    payeeEntry?: TAccountMetas[4] | undefined;
    request: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
    eventAuthority: TAccountMetas[7];
    program: TAccountMetas[8];
  };
  data: RequestPaymentInstructionData;
};

export function parseRequestPaymentInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRequestPaymentInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === LEASH_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      agentKey: getNextAccount(),
      rentPayer: getNextAccount(),
      principal: getNextAccount(),
      agent: getNextAccount(),
      payeeEntry: getNextOptionalAccount(),
      request: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getRequestPaymentInstructionDataDecoder().decode(instruction.data),
  };
}
